/// Prefix operators.
enum PrefixOperator {
    Minus, // -a
    Not,   // NOT a
    Plus,  // +a
}

impl PrefixOperator {
    /// The operator precedence.
    fn precedence(&self) -> Precedence {
        200
    }

    // The operator associativity. Prefix operators are right-associative by
    // definition.
    fn associativity(&self) -> Associativity {
        Associativity::Right
    }

    /// Builds an AST expression for the operator.
    fn into_expression(self, rhs: ast::Expression) -> ast::Expression {
        use ast::Operator::*;
        match self {
            PrefixOperator::Minus => Negate(Box::new(rhs)),
            PrefixOperator::Not => Not(Box::new(rhs)),
            PrefixOperator::Plus => Identity(Box::new(rhs)),
        }
    }
}

/// Infix operators.
enum InfixOperator {
    Add,                // a + b
    And,                // a AND b
    Divide,             // a / b
    Equal,              // a = b
    Exponentiate,       // a ^ b
    GreaterThan,        // a > b
    GreaterThanOrEqual, // a >= b
    LessThan,           // a < b
    LessThanOrEqual,    // a <= b
    Like,               // a LIKE b
    Multiply,           // a * b
    NotEqual,           // a != b
    Or,                 // a OR b
    Remainder,          // a % b
    Subtract,           // a - b
}

impl InfixOperator {
    /// The operator precedence.
    fn precedence(&self) -> Precedence {
        use InfixOperator::*;
        match self {
            And | Or => 10,
            Equal | NotEqual | GreaterThan | GreaterThanOrEqual | LessThan | LessThanOrEqual | Like => 20,
            Add | Subtract => 30,
            Multiply | Divide | Remainder => 40,
            Exponentiate => 50,
        }
    }

    /// The operator associativity.
    fn associativity(&self) -> Associativity {
        Associativity::Left
    }

    /// Builds an AST expression for the infix operator.
    fn into_expression(self, lhs: ast::Expression, rhs: ast::Expression) -> ast::Expression {
        use ast::Operator::*;
        match self {
            InfixOperator::Add => Add(Box::new(lhs), Box::new(rhs)),
            InfixOperator::And => And(Box::new(lhs), Box::new(rhs)),
            InfixOperator::Divide => Divide(Box::new(lhs), Box::new(rhs)),
            InfixOperator::Equal => Equal(Box::new(lhs), Box::new(rhs)),
            InfixOperator::Exponentiate => Exponentiate(Box::new(lhs), Box::new(rhs)),
            InfixOperator::GreaterThan => GreaterThan(Box::new(lhs), Box::new(rhs)),
            InfixOperator::GreaterThanOrEqual => GreaterThanOrEqual(Box::new(lhs), Box::new(rhs)),
            InfixOperator::LessThan => LessThan(Box::new(lhs), Box::new(rhs)),
            InfixOperator::LessThanOrEqual => LessThanOrEqual(Box::new(lhs), Box::new(rhs)),
            InfixOperator::Like => Like(Box::new(lhs), Box::new(rhs)),
            InfixOperator::Multiply => Multiply(Box::new(lhs), Box::new(rhs)),
            InfixOperator::NotEqual => NotEqual(Box::new(lhs), Box::new(rhs)),
            InfixOperator::Or => Or(Box::new(lhs), Box::new(rhs)),
            InfixOperator::Remainder => Remainder(Box::new(lhs), Box::new(rhs)),
            InfixOperator::Subtract => Subtract(Box::new(lhs), Box::new(rhs)),
        }
    }
}

/// Postfix operators.
enum PostfixOperator {
    Factorial,           // a!
    Is(ast::Literal),    // a IS NULL | NAN
    IsNot(ast::Literal), // a IS NOT NULL | NAN
}

impl PostfixOperator {
    // The operator precedence.
    fn precedence(&self) -> Precedence {
        200
    }

    /// Builds an AST expression for the operator.
    fn into_expression(self, lhs: ast::Expression) -> ast::Expression {
        use ast::Operator::*;
        match self {
            PostfixOperator::Factorial => Factorial(Box::new(lhs)),
            PostfixOperator::Is(lit) => Is(Box::new(lhs), lit),
            PostfixOperator::IsNot(lit) => {
                ast::Expression::Operator(Box::new(Not(Box::new(Is(Box::new(lhs), lit)))).into())
            }
        }
    }
}
